# Erratas puntuales en párrafos que no se reescriben (texto exacto -> corrección)
ERRATAS = {
    185: [("Molina en (2017)", "Molina (2017)")],
    186: [("cambios los curriculares", "cambios curriculares")],
    188: [("Gaviria y Lopera (2022)", "Giraldo Gaviria y Caro Lopera (2022)")],
}
BORRAR += [815]  # referencia de Morales Londoño (2018) repetida

W = qn("w:")


def limpiar_formato(run):
    rpr = run._r.rPr
    if rpr is None:
        return
    for tag in ("w:b", "w:bCs", "w:i", "w:iCs", "w:rStyle"):
        for el in rpr.findall(qn(tag)):
            rpr.remove(el)


def reemplazar(p, texto):
    runs = p.runs
    runs[0].text = texto
    limpiar_formato(runs[0])
    for r in runs[1:]:
        r._r.getparent().remove(r._r)


def reemplazar_tras_negrita(p, texto):
    # el primer run es el verbo del objetivo (en negrita por estilo o por formato)
    runs = p.runs
    runs[1].text = texto
    for r in runs[2:]:
        r._r.getparent().remove(r._r)


def errata(p, viejo, nuevo):
    for r in p.runs:
        if viejo in r.text:
            r.text = r.text.replace(viejo, nuevo)
            return
    texto = p.text
    assert viejo in texto, (viejo, texto[:80])
    reemplazar(p, texto.replace(viejo, nuevo))


def main(src, dst):
    d = docx.Document(src)
    P = d.paragraphs
    for i, t in FULL.items():
        reemplazar(P[i], t)
    for i, t in LEAD.items():
        reemplazar_tras_negrita(P[i], t)
    for i, cambios in ERRATAS.items():
        for v, n in cambios:
            errata(P[i], v, n)
    for i in sorted(BORRAR, reverse=True):
        el = P[i]._p
        el.getparent().remove(el)
    d.save(dst)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
